export function GridContainer({
  columns = "{{columns}}",
  rows = "{{rows}}",
  gap = {{gap}},
  alignItems = "{{alignItems}}",
}) {
  const cell = { background: "#D9C8F0", borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700, height: 30 };
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 320 }}
      role="img" aria-label="A grid container parenting six cells; column tracks, row height, gap and align-items are adjustable">
      <div style={{ display: "grid", gridTemplateColumns: columns, gridAutoRows: rows, gap, alignItems,
        background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box" }}>
        <div style={cell}>1</div><div style={cell}>2</div><div style={cell}>3</div>
        <div style={cell}>4</div><div style={cell}>5</div><div style={cell}>6</div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        columns: {columns} &middot; row height {rows} &middot; gap {gap}px &middot; align-items: {alignItems}
      </p>
    </div>
  );
}
